command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
$branch="work/release-source-identity-20261006"
$candidate="bc63c8b48e466d1275cc6dcffb0c50e02d39db60"
$baseline="6b91eaee6c268b422f21a83570e37dc9be2ed961"
$temp=Join-Path $env:RUNNER_TEMP ("release-source-acceptance-"+$env:GITHUB_RUN_ID)
$worktreeAdded=$false
try {
  Set-Location -LiteralPath $repo
  & git fetch origin main $branch --no-tags --prune
  if($LASTEXITCODE -ne 0){throw "candidate fetch failed"}
  $mainSha=(& git rev-parse refs/remotes/origin/main).Trim()
  $branchSha=(& git rev-parse ("refs/remotes/origin/"+$branch)).Trim()
  if($mainSha -ne $baseline){throw "main moved before release-source acceptance: $mainSha"}
  if($branchSha -ne $candidate){throw "candidate moved before release-source acceptance: $branchSha"}

  & git worktree add --detach $temp $candidate
  if($LASTEXITCODE -ne 0){throw "candidate worktree creation failed"}
  $worktreeAdded=$true
  Set-Location -LiteralPath $temp
  $env:PYTHONIOENCODING="utf-8"

  & git diff --check
  if($LASTEXITCODE -ne 0){throw "candidate diff check failed"}
  & python -X utf8 tools\winui\check_python_static.py packaging\source_bundle.py packaging\release_identity.py packaging\provenance.py packaging\package.py tests\winui\test_release_source_bundle_contract.py tests\winui\test_installed_lifecycle.py
  if($LASTEXITCODE -ne 0){throw "release source static check failed"}
  & python -X utf8 -m unittest tests.winui.test_release_source_bundle_contract tests.winui.test_release_payload_contract tests.winui.test_installer_contract
  if($LASTEXITCODE -ne 0){throw "release source/package contracts failed"}

  & .\clean.bat build
  if($LASTEXITCODE -ne 0){throw "clean build output failed"}
  & .\build.bat Release
  if($LASTEXITCODE -ne 0){throw "canonical Release build failed"}

  & python -X utf8 packaging\provenance.py --write
  if($LASTEXITCODE -ne 0){throw "runtime provenance generation failed"}
  & python -X utf8 packaging\provenance.py --check
  if($LASTEXITCODE -ne 0){throw "runtime provenance verification failed"}

  & .\package.bat Release
  if($LASTEXITCODE -ne 0){throw "Release package build failed"}

  & python -X utf8 packaging\source_bundle.py --write --revision $candidate
  if($LASTEXITCODE -ne 0){throw "source bundle generation failed"}
  & python -X utf8 packaging\source_bundle.py --check --revision $candidate
  if($LASTEXITCODE -ne 0){throw "source bundle verification failed"}

  $bundle=Join-Path $temp ("out\release\flyExplorer-source-"+$candidate+".zip")
  $sourceManifest=Join-Path $temp ("out\release\flyExplorer-source-"+$candidate+".manifest.json")
  $identity=Join-Path $temp "out\release\RELEASE_IDENTITY.json"
  $setup=Join-Path $temp "out\package\flyExplorer-Setup-x64.exe"

  & python -X utf8 packaging\release_identity.py --write --source-bundle $bundle --source-manifest $sourceManifest --setup $setup --identity $identity
  if($LASTEXITCODE -ne 0){throw "release identity generation failed"}
  & python -X utf8 packaging\release_identity.py --check --source-bundle $bundle --source-manifest $sourceManifest --setup $setup --identity $identity
  if($LASTEXITCODE -ne 0){throw "release identity verification failed"}

  & python -X utf8 tests\winui\test_installed_lifecycle.py
  if($LASTEXITCODE -ne 0){throw "bounded installed lifecycle failed"}

  $prov=Get-Content -Raw -Encoding UTF8 -LiteralPath "packaging\licenses\PAYLOAD_PROVENANCE.json" | ConvertFrom-Json
  $source=Get-Content -Raw -Encoding UTF8 -LiteralPath $sourceManifest | ConvertFrom-Json
  $release=Get-Content -Raw -Encoding UTF8 -LiteralPath $identity | ConvertFrom-Json
  if($prov.runtime_source_revision -ne $candidate){throw "runtime source revision mismatch"}
  if($source.source_revision -ne $candidate){throw "source bundle revision mismatch"}
  if($release.binary_source_revision -ne $candidate){throw "release identity source revision mismatch"}
  if($release.runtime.manifest_sha256 -ne $prov.runtime_manifest_sha256){throw "release/runtime manifest mismatch"}
  if($release.source_bundle.sha256 -ne $source.bundle_sha256){throw "release/source bundle digest mismatch"}

  $changed=@(& git diff --name-only)
  if($LASTEXITCODE -ne 0){throw "failed to inspect generated provenance diff"}
  $expected=@("packaging/licenses/PAYLOAD_PROVENANCE.json","packaging/licenses/PAYLOAD_PROVENANCE.md")
  $unexpected=@($changed | Where-Object { $_ -notin $expected })
  $missing=@($expected | Where-Object { $_ -notin $changed })
  if($unexpected.Count -gt 0 -or $missing.Count -gt 0){
    throw ("unexpected tracked changes before identity record: "+($changed -join ","))
  }

  $evidence=Join-Path $env:FLYEXPLORER_CANONICAL_CHECKOUT "logs\remote-evidence\release-source-identity"
  New-Item -ItemType Directory -Force -Path $evidence | Out-Null
  Copy-Item -LiteralPath $setup -Destination (Join-Path $evidence "flyExplorer-Setup-x64.exe") -Force
  Copy-Item -LiteralPath $bundle -Destination (Join-Path $evidence ([IO.Path]::GetFileName($bundle))) -Force
  Copy-Item -LiteralPath $sourceManifest -Destination (Join-Path $evidence ([IO.Path]::GetFileName($sourceManifest))) -Force
  Copy-Item -LiteralPath $identity -Destination (Join-Path $evidence "RELEASE_IDENTITY.json") -Force
  Copy-Item -LiteralPath "packaging\licenses\PAYLOAD_PROVENANCE.json" -Destination (Join-Path $evidence "PAYLOAD_PROVENANCE.json") -Force
  Copy-Item -LiteralPath "packaging\licenses\PAYLOAD_PROVENANCE.md" -Destination (Join-Path $evidence "PAYLOAD_PROVENANCE.md") -Force

  Write-Host ("FINAL_RELEASE_SOURCE_REVISION="+$candidate)
  Write-Host ("FINAL_RELEASE_SOURCE_TREE_SHA="+$source.source_tree_sha)
  Write-Host ("FINAL_RELEASE_SOURCE_FILES="+$source.file_count)
  Write-Host ("FINAL_RELEASE_SOURCE_BUNDLE_SHA256="+$source.bundle_sha256)
  Write-Host ("FINAL_RELEASE_RUNTIME_MANIFEST_SHA256="+$prov.runtime_manifest_sha256)
  Write-Host ("FINAL_RELEASE_SETUP_SHA256="+$release.setup.sha256)
  Write-Host ("FINAL_RELEASE_SETUP_BYTES="+$release.setup.bytes)

  Copy-Item -LiteralPath $sourceManifest -Destination "packaging\SOURCE_BUNDLE_MANIFEST.json" -Force
  Copy-Item -LiteralPath $identity -Destination "packaging\RELEASE_IDENTITY.json" -Force
  & git diff --check
  if($LASTEXITCODE -ne 0){throw "generated release record diff check failed"}

  Set-Location -LiteralPath $repo
  & git fetch origin main $branch --no-tags
  if($LASTEXITCODE -ne 0){throw "pre-push fetch failed"}
  $latestMain=(& git rev-parse refs/remotes/origin/main).Trim()
  $latestBranch=(& git rev-parse ("refs/remotes/origin/"+$branch)).Trim()
  if($latestMain -ne $baseline){throw "main moved during acceptance: $latestMain"}
  if($latestBranch -ne $candidate){throw "candidate branch moved during acceptance: $latestBranch"}

  Set-Location -LiteralPath $temp
  & git add -- packaging/licenses/PAYLOAD_PROVENANCE.json packaging/licenses/PAYLOAD_PROVENANCE.md packaging/SOURCE_BUNDLE_MANIFEST.json packaging/RELEASE_IDENTITY.json
  if($LASTEXITCODE -ne 0){throw "failed to stage accepted release identity records"}
  & git -c user.name="flyExplorer automation" -c user.email="actions@flyexplorer.local" commit -m "build: record accepted binary source identity"
  if($LASTEXITCODE -ne 0){throw "failed to commit accepted release identity records"}
  $recordCommit=(& git rev-parse HEAD).Trim()
  & git push origin ("HEAD:refs/heads/"+$branch)
  if($LASTEXITCODE -ne 0){throw "failed to push accepted release identity records"}
  Write-Host ("FINAL_RELEASE_IDENTITY_COMMIT="+$recordCommit)
  Write-Host "RELEASE_SOURCE_IDENTITY_ACCEPTANCE=PASS"
} finally {
  Set-Location -LiteralPath $repo
  if($worktreeAdded){
    & git worktree remove --force $temp 2>$null
    & git worktree prune
  } elseif(Test-Path -LiteralPath $temp) {
    Remove-Item -LiteralPath $temp -Recurse -Force -ErrorAction SilentlyContinue
  }
}
